"""Bounded model protocol shared by real and explicitly injected fixture models."""

import json
from dataclasses import dataclass
from decimal import Decimal
from typing import Any, Protocol


class ModelConfigurationError(ValueError):
    pass


class ModelProviderError(RuntimeError):
    """Safe error without the provider request, credentials, or response body."""


class ModelContextLimit(ValueError):
    pass


@dataclass(frozen=True)
class ModelUsage:
    input_tokens: int
    output_tokens: int
    cost_usd: Decimal | None


@dataclass(frozen=True)
class ModelResponse:
    message: dict[str, Any]
    usage: ModelUsage
    model_id: str
    finish_reason: str


class ToolCallingModel(Protocol):
    model_id: str

    def maximum_request_cost(self, messages: list[dict[str, Any]], tools: list[dict[str, Any]]) -> Decimal: ...

    async def complete(self, messages: list[dict[str, Any]], tools: list[dict[str, Any]]) -> ModelResponse: ...


@dataclass(frozen=True)
class ModelRates:
    """Operator supplied USD rates snapshot, per million tokens; no guessed prices."""

    input_per_million: Decimal
    output_per_million: Decimal

    def __post_init__(self) -> None:
        for value in (self.input_per_million, self.output_per_million):
            if not value.is_finite() or value < 0:
                raise ModelConfigurationError("model rates must be finite and nonnegative")

    def cost(self, input_tokens: int, output_tokens: int) -> Decimal:
        if input_tokens < 0 or output_tokens < 0:
            raise ValueError("negative token usage")
        return (self.input_per_million * input_tokens + self.output_per_million * output_tokens) / Decimal(1_000_000)


def conservative_input_tokens(messages: list[dict[str, Any]], tools: list[dict[str, Any]]) -> int:
    """Bound by UTF-8 bytes plus protocol overhead instead of undercounting chars.

    This deliberately overestimates typical BPE input. The operator's context
    window and output cap still bound every request; actual provider usage is
    accounted separately. No tool output is silently dropped from conversation.
    """
    payload = json.dumps({"messages": messages, "tools": tools}, ensure_ascii=False, allow_nan=False)
    return len(payload.encode("utf-8")) + 4096 + 256 * len(messages)
"""A single explicit provider/model serves all Phase 2 role profiles."""

from agentforge.settings import Settings

from .models import ModelConfigurationError, ModelRates, ToolCallingModel
from .openai_adapter import OpenAIAdapter


class ModelRouter:
    def __init__(self, model: ToolCallingModel) -> None:
        self.model = model

    def choose(self, profile: str) -> ToolCallingModel:
        if profile not in ("default", "research", "coding", "review"):
            raise ModelConfigurationError("unknown model profile")
        return self.model

    @classmethod
    def from_settings(cls, settings: Settings) -> "ModelRouter":
        if settings.llm_provider != "openai":
            raise ModelConfigurationError("only the explicit OpenAI adapter is installed")
        if not settings.llm_model or settings.llm_api_key is None or settings.llm_context_window_tokens is None:
            raise ModelConfigurationError("LLM_MODEL, LLM_API_KEY and LLM_CONTEXT_WINDOW_TOKENS are required")
        if settings.llm_input_usd_per_million is None or settings.llm_output_usd_per_million is None:
            raise ModelConfigurationError("explicit model input and output rates are required")
        if not settings.llm_supports_tools or not settings.llm_supports_json:
            raise ModelConfigurationError("operator must verify configured model tool calling and JSON support")
        return cls(OpenAIAdapter(
            api_key=settings.llm_api_key.get_secret_value(), model_id=settings.llm_model,
            rates=ModelRates(settings.llm_input_usd_per_million, settings.llm_output_usd_per_million),
            context_window_tokens=settings.llm_context_window_tokens,
            max_output_tokens=settings.llm_max_output_tokens, timeout_sec=settings.llm_timeout_sec,
            reasoning_effort=settings.llm_reasoning_effort,
        ))
"""Revocable local sessions; never accept a client-supplied identity."""

from dataclasses import dataclass
from hashlib import sha256
from ipaddress import ip_address
from secrets import token_urlsafe
from threading import Lock
from time import monotonic
from urllib.parse import urlsplit
from uuid import UUID

from fastapi import HTTPException, Request
from sqlalchemy.orm import Session

from agentforge.database.models import User
from agentforge.settings import Settings

COOKIE_NAME = "agentforge_local_session"


@dataclass(frozen=True)
class LocalSession:
    user_id: UUID
    expires_at: float


class SessionStore:
    """Process-local by design: restarting the API revokes every session."""

    def __init__(self) -> None:
        self._sessions: dict[str, LocalSession] = {}
        self._lock = Lock()

    def issue(self, user_id: UUID, ttl: int) -> str:
        token = token_urlsafe(48)
        now = monotonic()
        with self._lock:
            self._sessions = {key: value for key, value in self._sessions.items()
                              if value.expires_at > now}
            # Local setup should not create an unbounded session registry.
            if len(self._sessions) >= 32:
                oldest = min(self._sessions, key=lambda key: self._sessions[key].expires_at)
                del self._sessions[oldest]
            self._sessions[sha256(token.encode()).hexdigest()] = LocalSession(user_id, now + ttl)
        return token

    def resolve(self, token: str | None) -> LocalSession | None:
        if not token or len(token) > 128:
            return None
        key = sha256(token.encode()).hexdigest()
        with self._lock:
            result = self._sessions.get(key)
            if result and result.expires_at <= monotonic():
                del self._sessions[key]
                return None
            return result

    def revoke(self, token: str | None) -> None:
        if token:
            with self._lock:
                self._sessions.pop(sha256(token.encode()).hexdigest(), None)


def local_auth_enabled(settings: Settings) -> bool:
    token = settings.local_bootstrap_token
    return (settings.app_env != "production" and settings.auth_mode == "local_single_user"
            and settings.local_user_id is not None and token is not None
            and len(token.get_secret_value()) >= 32)


def _loopback(host: str | None) -> bool:
    if host == "localhost":
        return True
    try:
        return ip_address(host or "").is_loopback
    except ValueError:
        return False


