    except TaskNotFound:
        raise HTTPException(404, "task_not_found") from None
    if cursor > task.event_sequence:
        raise HTTPException(409, "event_cursor_ahead_of_task")
    event_repository = EventRepository(sessions(request))

    async def stream():
        nonlocal cursor
        yield "retry: 3000\n\n"
        idle_cycles = 0
